#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Diagnostics;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class ArchiveSfxTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();Action<bool,string> check=(ok,text)=>{if(!ok)throw new Exception(text);log.Add(text);};try{
   FluentTheme.Ensure();L.ChangeLanguage("cs");var settings=new ArchiveSettings{WinRarPath=ArchiveSettings.FindWinRar()??"",ArjPath=Path.GetFullPath(Path.Combine(root,"..","..","sfx-research","arj","ARJ32.EXE"))};
   if(File.Exists(settings.WinRarPath)){ToolTrust.Approve(settings.WinRarPath);ToolTrust.Approve(settings.RarExecutable());}if(File.Exists(settings.ArjPath))ToolTrust.Approve(settings.ArjPath);settings.Save();
   string input=Path.Combine(root,"hello.txt");File.WriteAllText(input,"SFX fixture with actual content");
   foreach(string format in new[]{"7z","zip","rar","arj"}){
    if(format=="arj"&&!File.Exists(settings.ArjPath))throw new Exception("ARJ32 fixture missing: "+settings.ArjPath);
    string target=Path.Combine(root,format+".exe");ArchiveEngine.Create(target,new[]{input},settings,CancellationToken.None,null,new ArchivePackOptions{SelfExtracting=true,Format=format});
    var doc=ArchiveEngine.Open(target);check(doc.Items.Any(x=>x.Path=="hello.txt"),format+" EXE contains the selected archive member");string extracted=Path.Combine(root,"library-"+format);ArchiveEngine.Extract(doc,new[]{"hello.txt"},extracted,CancellationToken.None);check(File.ReadAllText(Path.Combine(extracted,"hello.txt"))==File.ReadAllText(input),format+" SFX verifies and extracts through the archive engine");
    string standalone=Path.Combine(root,"standalone-"+format);Directory.CreateDirectory(standalone);string args=format=="7z"?"-y -o"+SshTerminal.QuoteWindowsArgument(standalone):format=="arj"?"-y":"-s -d"+SshTerminal.QuoteWindowsArgument(standalone);
    using(var child=Process.Start(new ProcessStartInfo(ArchiveSelfExtract.ExecutablePath(target),args){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=standalone})){if(!child.WaitForExit(15000)){child.Kill();child.WaitForExit();throw new Exception(format+" standalone SFX did not exit");}check(child.ExitCode==0&&File.Exists(Path.Combine(standalone,"hello.txt"))&&File.ReadAllText(Path.Combine(standalone,"hello.txt"))==File.ReadAllText(input),format+" standalone executable really extracts the payload");}
   }
   foreach(string format in new[]{"7z","zip"}){string target=Path.Combine(root,format+"-secret.exe");ArchiveEngine.Create(target,new[]{input},settings,CancellationToken.None,null,new ArchivePackOptions{SelfExtracting=true,Format=format,Password="Fixture-password"});var doc=ArchiveEngine.Open(target,"Fixture-password");ArchiveEngine.Test(doc,CancellationToken.None);check(doc.Items.Any(x=>x.Encrypted),format+" SFX retains password-protected payload");}
   string moved=Path.Combine(root,"move.txt");File.WriteAllText(moved,"move fixture");string moveTarget=Path.Combine(root,"moved.exe");ArchiveEngine.Create(moveTarget,new[]{moved},settings,CancellationToken.None,null,new ArchivePackOptions{SelfExtracting=true,Format="7z",Move=true});check(!File.Exists(moved)&&ArchiveEngine.Open(moveTarget).Items.Any(x=>x.Path=="move.txt"),"SFX move deletes sources only after final verification");
   var random=new byte[65536];new Random(11).NextBytes(random);string bulk=Path.Combine(root,"bulk.bin");File.WriteAllBytes(bulk,random);string split=Path.Combine(root,"split.exe");ArchiveEngine.Create(split,new[]{bulk},settings,CancellationToken.None,null,new ArchivePackOptions{SelfExtracting=true,Format="7z",VolumeBytes=16384});check(File.Exists(split)&&File.Exists(Path.ChangeExtension(split,"7z")+".002"),"split 7z SFX publishes a launcher and numbered volumes");var divided=ArchiveEngine.Open(Path.ChangeExtension(split,"7z")+".001");ArchiveEngine.Test(divided,CancellationToken.None);check(divided.Items.Any(x=>x.Path=="bulk.bin"),"split 7z SFX payload remains complete");
   string splitOut=Path.Combine(root,"standalone-split");Directory.CreateDirectory(splitOut);using(var child=Process.Start(new ProcessStartInfo(split,"-y -o"+SshTerminal.QuoteWindowsArgument(splitOut)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){if(!child.WaitForExit(15000)){child.Kill();child.WaitForExit();throw new Exception("split launcher timed out");}check(child.ExitCode==0&&FileParts.Hash(Path.Combine(splitOut,"bulk.bin"),CancellationToken.None)==FileParts.Hash(bulk,CancellationToken.None),"standalone 7z SFX launcher extracts its numbered volumes");}
   bool cancelled=false;using(var stop=new CancellationTokenSource()){stop.Cancel();try{ArchiveEngine.Create(Path.Combine(root,"cancel.exe"),new[]{input},settings,stop.Token,null,new ArchivePackOptions{SelfExtracting=true,Format="7z"});}catch(OperationCanceledException){cancelled=true;}}check(cancelled&&!File.Exists(Path.Combine(root,"cancel.exe")),"cancelled SFX creation never publishes a partial executable");
      string motif=AppearanceTheme.Motif;AppearanceTheme.SetMotif("Clean");var ui=new ArchivePackDialog(null,1,Path.Combine(root,"ui.zip")){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false,ShowInTaskbar=false};try{ui.Show();NavigationTests.Wait(System.Threading.Tasks.Task.Delay(150));var formatChoice=FluentUiTests.Children<ComboBox>(ui).Single(x=>x.Items.Cast<object>().Any(v=>Convert.ToString(v)=="7-ZIP"));var sfx=FluentUiTests.Children<CheckBox>(ui).Single(x=>Convert.ToString(x.Content)==L.Text("archive.selfExtracting"));formatChoice.SelectedItem="7-ZIP";sfx.IsChecked=true;ui.UpdateLayout();check(sfx.IsEnabled&&FluentUiTests.Children<Button>(ui).Any(x=>Convert.ToString(x.Content)==L.Text("archive.withSfx"))&&FluentUiTests.Children<TextBox>(ui).Any(x=>x.Text=="ui.exe"),"dialog enables 7z SFX, updates the EXE name and summary");formatChoice.SelectedItem="TAR";check(!sfx.IsEnabled&&sfx.IsChecked==false&&FluentUiTests.Children<TextBox>(ui).Any(x=>x.Text=="ui.tar"),"unsupported format clears SFX and restores its normal extension");NextStageTests.Draw(ui,Path.Combine(root,"sfx-dialog.png"));}finally{ui.Close();AppearanceTheme.SetMotif(motif);}
   File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
  }catch(Exception ex){   string motif=AppearanceTheme.Motif;AppearanceTheme.SetMotif("Clean");var ui=new ArchivePackDialog(null,1,Path.Combine(root,"ui.zip")){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false,ShowInTaskbar=false};try{ui.Show();NavigationTests.Wait(System.Threading.Tasks.Task.Delay(150));var formatChoice=FluentUiTests.Children<ComboBox>(ui).Single(x=>x.Items.Cast<object>().Any(v=>Convert.ToString(v)=="7-ZIP"));var sfx=FluentUiTests.Children<CheckBox>(ui).Single(x=>Convert.ToString(x.Content)==L.Text("archive.selfExtracting"));formatChoice.SelectedItem="7-ZIP";sfx.IsChecked=true;ui.UpdateLayout();check(sfx.IsEnabled&&FluentUiTests.Children<Button>(ui).Any(x=>Convert.ToString(x.Content)==L.Text("archive.withSfx"))&&FluentUiTests.Children<TextBox>(ui).Any(x=>x.Text=="ui.exe"),"dialog enables 7z SFX, updates the EXE name and summary");formatChoice.SelectedItem="TAR";check(!sfx.IsEnabled&&sfx.IsChecked==false&&FluentUiTests.Children<TextBox>(ui).Any(x=>x.Text=="ui.tar"),"unsupported format clears SFX and restores its normal extension");NextStageTests.Draw(ui,Path.Combine(root,"sfx-dialog.png"));}finally{ui.Close();AppearanceTheme.SetMotif(motif);}
   File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}}
 }
}
#endif